# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 4096}, num_warps=4),
        triton.Config({"BLOCK_SIZE": 8192}, num_warps=8),
    ],
    key=["n_cols"],
)
@triton.jit
def smooth_l1_row_kernel(
    predictions_ptr,
    targets_ptr,
    row_sums_ptr,
    n_cols,
    stride_pred,
    stride_targ,
    BLOCK_SIZE: tl.constexpr,
):
    row_idx = tl.program_id(0)

    pred_row_start = row_idx * stride_pred
    targ_row_start = row_idx * stride_targ

    row_sum = 0.0

    for col_start in range(0, n_cols, BLOCK_SIZE):
        col_offsets = col_start + tl.arange(0, BLOCK_SIZE)
        mask = col_offsets < n_cols

        pred = tl.load(
            predictions_ptr + pred_row_start + col_offsets, mask=mask, other=0.0
        ).to(tl.float32)
        targ = tl.load(
            targets_ptr + targ_row_start + col_offsets, mask=mask, other=0.0
        ).to(tl.float32)

        diff = pred - targ
        abs_diff = tl.abs(diff)
        loss = tl.where(abs_diff < 1.0, 0.5 * diff * diff, abs_diff - 0.5)

        row_sum += tl.sum(loss, axis=0)

    tl.store(row_sums_ptr + row_idx, row_sum)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, predictions, targets):
        predictions = predictions.contiguous()
        targets = targets.contiguous()

        n_rows = predictions.shape[0]
        n_cols = predictions.shape[1] if predictions.ndim > 1 else predictions.numel()
        n_elements = predictions.numel()

        row_sums = torch.empty(n_rows, device=predictions.device, dtype=torch.float32)

        grid = (n_rows,)
        smooth_l1_row_kernel[grid](
            predictions,
            targets,
            row_sums,
            n_cols,
            predictions.stride(0) if predictions.ndim > 1 else n_cols,
            targets.stride(0) if targets.ndim > 1 else n_cols,
        )

        return row_sums.sum() / n_elements
